// </themes>

class ThemeManager {
	constructor() {
		let saved = null;
		try { saved = localStorage.getItem('sigil_theme'); } catch (e) { /* storage blocked */ }
		this.current = saved && THEMES[saved] ? saved : 'default';
		this.apply(this.current);
		// The board <img> is not parsed yet when this runs in <head>, and some
		// pages mount it later (multiplayer's x-if playing template), so theme
		// every board as it is inserted.
		const watch = () => {
			this.applyBoard();
			new MutationObserver((records) => {
				if (records.some(r => r.addedNodes.length)) this.applyBoard();
			}).observe(document.body, { childList: true, subtree: true });
		};
		if (document.body) watch();
		else document.addEventListener('DOMContentLoaded', watch);
	}

	apply(themeId) {
		const theme = THEMES[themeId];
		if (!theme) return;
		const root = document.documentElement;

		// Clear all theme vars first
		for (const t of Object.values(THEMES)) {
			for (const k of Object.keys(t.vars || {})) {
				root.style.removeProperty(k);
			}
		}

		// Set data-theme attribute for image selectors
		root.setAttribute('data-theme', themeId);

		// Apply new vars
		for (const [k, v] of Object.entries(theme.vars || {})) {
			root.style.setProperty(k, v);
		}

		this.current = themeId;
		try { localStorage.setItem('sigil_theme', themeId); } catch (e) { /* storage blocked */ }
		this.applyBoard();
	}

	// Point every printed board (<picture><source webp><img jpg>) at the
	// theme's pre-rendered art. The original paths are kept in data-board-src
	// so switching back to Arcane restores them.
	applyBoard() {
		const theme = THEMES[this.current];
		for (const img of document.querySelectorAll('img.game-board')) {
			if (img.dataset.boardTheme === this.current) continue;
			img.dataset.boardTheme = this.current;
			const pic = img.parentElement && img.parentElement.tagName === 'PICTURE' ? img.parentElement : null;
			const src = pic && pic.querySelector('source[type="image/webp"]');
			if (!img.dataset.boardSrc) {
				img.dataset.boardSrc = img.getAttribute('src');
				if (src) src.dataset.boardSrc = src.getAttribute('srcset');
			}
			const themed = (orig, ext) => theme.board
				? orig.replace(/game-board\.(jpg|webp)$/, `themes/game-board-${this.current}.${ext}`)
				: orig;
			if (src) src.setAttribute('srcset', themed(src.dataset.boardSrc, 'webp'));
			img.setAttribute('src', themed(img.dataset.boardSrc, 'jpg'));
		}
	}

	getThemeList() {
		return Object.entries(THEMES).map(([id, t]) => ({ id, name: t.name }));
	}
}

const themeManager = new ThemeManager();
